import data from "../data/sources-tfh.json";
import rnc from "../data/sources-tfh-rnc.json";
import type { SourcePost } from "./aan-sources";
import { isReleased, tfhId } from "./releases";

// RN Collins, Tech From Here: NL. Generated by aan-studio/renders/sources_export.py tfh in
// rn-content-second-brain; do not edit by hand. These sets have no posting dates yet, so each
// page is addressed by its set number: /sources/tfh/<id>.
// The DDW26 RN Collins carousels and the Beyond DDW carousels (/sources/tfh/ddw26-rnc-NNN, /sources/tfh/bey-NNN) are in
// data/sources-tfh-rnc.json, generated by RN_COLLINS_v3.19/render-kit/sources_export_ddw26_rnc.py; do not edit it by hand either.
export const tfhPosts: SourcePost[] = [...(data.posts as SourcePost[]), ...(rnc.posts as SourcePost[])];

// Beyond DDW posts (bey-NNN) are not Dutch Design Week posts.
export const isBeyond = (p: { slug: string }) => p.slug.startsWith("bey-");

export function tfhPost(slug: string) {
  return tfhPosts.find((p) => p.slug === slug);
}

// A set's page exists, and is listed (index, sitemap), only once it is released in data/releases.json
// (lib/releases.ts). These sets have no posting dates yet, so every address returns 404 until RN dates them.
export function tfhPostedSoFar(now = new Date()) {
  return tfhPosts.filter((p) => isReleased(tfhId(p.slug), now));
}

export function releasedTfhPost(slug: string, now = new Date()) {
  const p = tfhPost(slug);
  return p && isReleased(tfhId(slug), now) ? p : undefined;
}
